// Package regen serializes the tests that regenerate the tree. go test runs each
// package's tests in its own process, in parallel with the other packages', and this
// module has two kinds of test that regenerate: cmd/generate's, which runs go generate
// ./... and compares the tree before and after, and each generate program's warnings
// test, which runs the generator in-process. Two generations over one module at once
// race in the generated files and in the generation cache, so each of those tests takes
// the module's generation lock first. Whichever of them takes the lock first
// regenerates the tree, and the ones after it find it already regenerated, so no one test
// can hold the comparison: Exclusive hashes the generated files when it has the lock and
// again when the test ends, and fails the test whose generation changed one.
package regen

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/go-playground/errors/v5"
)

// generatedHeader opens every Go file the generator writes, whatever the file is named.
const generatedHeader = "// Code generated by resourcegeneration. DO NOT EDIT."

// Exclusive takes the module's generation lock for the test and releases it when the
// test ends. The lock is a file under the temporary directory named for this module's
// root, so every test process of this module waits on the same one. It hashes the
// module's generated files when it has the lock and again when the test ends, and fails
// the test if one differs, is new or is gone: the generation the test ran changed what
// is on disk.
func Exclusive(t *testing.T) {
	t.Helper()

	root, err := moduleRoot()
	if err != nil {
		t.Fatalf("regen.Exclusive: %v", err)
	}
	finish, err := exclusive(root)
	if err != nil {
		t.Fatalf("regen.Exclusive: %v", err)
	}
	t.Cleanup(func() {
		changed, err := finish()
		if err != nil {
			t.Errorf("regen.Exclusive: %v", err)
		}
		if len(changed) > 0 {
			t.Errorf("generator output differs from the state on disk; if the change is intentional, commit the regenerated files:\n%s", strings.Join(changed, "\n"))
		}
	})
}

// exclusive takes the lock of the module rooted at root and hashes its generated files.
// The function it returns hashes them again, then releases the lock, and returns the
// files that changed in between with the first error of the two.
func exclusive(root string) (finish func() ([]string, error), err error) {
	release, err := acquire(root)
	if err != nil {
		return nil, err
	}
	before, err := hashGenerated(root)
	if err != nil {
		_ = release()

		return nil, errors.Wrap(err, "hashing the generated files")
	}
	finish = func() ([]string, error) {
		after, hashErr := hashGenerated(root)
		releaseErr := release()
		switch {
		case hashErr != nil:
			return nil, errors.Wrap(hashErr, "hashing the generated files")
		case releaseErr != nil:
			return changedFiles(before, after), errors.Wrap(releaseErr, "releasing the generation lock")
		}

		return changedFiles(before, after), nil
	}

	return finish, nil
}

// acquire waits until the lock of the module rooted at root is held and returns the
// function that releases it.
func acquire(root string) (func() error, error) {
	sum := sha256.Sum256([]byte(root))
	name := filepath.Join(os.TempDir(), "generation-"+hex.EncodeToString(sum[:8])+".lock")
	f, err := os.OpenFile(name, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, errors.Wrap(err, "os.OpenFile()")
	}
	if err := lock(f); err != nil {
		_ = f.Close()

		return nil, err
	}
	release := func() error {
		if err := unlock(f); err != nil {
			_ = f.Close()

			return err
		}
		if err := f.Close(); err != nil {
			return errors.Wrap(err, "os.File.Close()")
		}

		return nil
	}

	return release, nil
}

// hashGenerated maps every generated file under the module rooted at root to its content
// hash, by its path relative to the root: every zz_gen file, and every Go file that opens
// with the generator's header, which is how the files of a tree the generator owns whole
// are told (the generated management of the auths, GenerateIdentity: its sources carry
// plain names). No directory is named, so the comparison holds wherever a program writes
// such a tree. The Angular workspaces' node_modules, .angular and dist are excluded.
func hashGenerated(root string) (map[string][32]byte, error) {
	// The files that may be generated: the zz_gen files, and every Go file, which is
	// read below to see whether it opens with the header.
	named := map[string]bool{}
	var paths []string
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == "node_modules" || d.Name() == ".angular" || d.Name() == "dist" {
				return filepath.SkipDir
			}

			return nil
		}
		if strings.Contains(d.Name(), "zz_gen") {
			named[path] = true
		}
		if named[path] || strings.HasSuffix(d.Name(), ".go") {
			paths = append(paths, path)
		}

		return nil
	})
	if err != nil {
		return nil, errors.Wrap(err, "filepath.WalkDir()")
	}

	sums := make(map[string][32]byte)
	for _, path := range paths {
		raw, err := os.ReadFile(path)
		if err != nil {
			return nil, errors.Wrap(err, "os.ReadFile()")
		}
		if !named[path] && !bytes.HasPrefix(raw, []byte(generatedHeader)) {
			continue
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return nil, errors.Wrap(err, "filepath.Rel()")
		}
		sums[rel] = sha256.Sum256(raw)
	}

	return sums, nil
}

// changedFiles lists the paths whose hash differs between before and after or that are
// new in after, then each path of before that is gone from after as "<path> (removed)",
// sorted.
func changedFiles(before, after map[string][32]byte) []string {
	var changed, removed []string
	for path, sum := range after {
		if was, ok := before[path]; !ok || was != sum {
			changed = append(changed, path)
		}
	}
	for path := range before {
		if _, ok := after[path]; !ok {
			removed = append(removed, path+" (removed)")
		}
	}
	slices.Sort(changed)
	slices.Sort(removed)

	return append(changed, removed...)
}

// moduleRoot is the directory holding go.mod at or above the working directory (go test
// runs a package's tests in that package's directory).
func moduleRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", errors.Wrap(err, "os.Getwd()")
	}
	for {
		_, err := os.Stat(filepath.Join(dir, "go.mod"))
		if err == nil {
			return dir, nil
		}
		if !errors.Is(err, fs.ErrNotExist) {
			return "", errors.Wrap(err, "os.Stat()")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", errors.New("no go.mod at or above the working directory")
		}
		dir = parent
	}
}
